"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { X } from "./icons";

// Modal: generated by UIX from the design system. Same variants and sizes as the Figma component.

const modalVariants = cva(
  "m-auto w-[calc(100%_-_2rem)] max-h-[calc(100dvh_-_2rem)] overflow-y-auto p-0 bg-surface text-fg-primary shadow-xl backdrop:bg-base-black/50 rounded-2xl",
  {
    variants: {
      size: {
        sm: "max-w-[400px]",
        md: "max-w-[560px]",
        lg: "max-w-[720px]",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface ModalProps
  extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "title" | "open" | "onClose">,
    VariantProps<typeof modalVariants> {
  open: boolean;
  onClose: () => void;
  title?: React.ReactNode;
  /** Icon in a round badge above the title. */
  headerIcon?: React.ReactNode;
  /** Set to false to hide the close button in the corner. */
  showClose?: boolean;
  /** Buttons, right-aligned under the content. */
  footer?: React.ReactNode;
}

const Modal = React.forwardRef<HTMLDialogElement, ModalProps>(
  ({ className, size, open, onClose, title, headerIcon, showClose = true, footer, children, ...props }, ref) => {
    const inner = React.useRef<HTMLDialogElement>(null);
    React.useImperativeHandle(ref, () => inner.current as HTMLDialogElement);
    React.useEffect(() => {
      const dialog = inner.current;
      if (!dialog) return;
      if (open && !dialog.open) dialog.showModal();
      if (!open && dialog.open) dialog.close();
    }, [open]);
    const titleId = React.useId();
    return (
      <dialog data-slot="modal" data-kind="overlay"
        ref={inner}
        aria-labelledby={title ? titleId : void 0}
        className={cn(modalVariants({ size }), className)}
        onClose={onClose}
        onClick={(event) => {
          if (event.target === event.currentTarget) onClose();
        }}
        {...props}
      >
        <div className="flex flex-col gap-4 p-6">
          {headerIcon ? <span aria-hidden className="inline-flex items-center justify-center rounded-full size-10 bg-brand-subtle text-icon-brand">{headerIcon}</span> : null}
          <div className="flex items-start justify-between gap-3">
            {title ? (
              <h2 id={titleId} className="text-heading-5 text-fg-primary">
                {title}
              </h2>
            ) : (
              <span />
            )}
            {showClose ? (
              <button type="button" aria-label="Close" onClick={onClose} className="inline-flex shrink-0 cursor-pointer items-center justify-center size-8 rounded-sm text-icon-secondary hover:bg-subtle focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
                <X aria-hidden className="size-5" />
              </button>
            ) : null}
          </div>
          <div className="text-body-medium text-fg-secondary">{children}</div>
          {footer ? <div className="flex justify-end gap-2">{footer}</div> : null}
        </div>
      </dialog>
    );
  },
);
Modal.displayName = "Modal";

export { Modal, modalVariants };
